def period(CMNDF : np.ndarray, thresh : float=0.4):
    T = 0
    min = thresh
    for tau in range(len(CMNDF)):
        # finding nearest lowest point below thresh
        if CMNDF[tau] < thresh:
            if CMNDF[tau] < min:
                min = CMNDF[tau]
                T = tau

    return T

def robot(x : np.ndarray, period : int):
    X = np.fft.rfft(x, period)
    new_X = np.abs(X)
    return np.fft.irfft(new_X, period)

