def find_nearest(array : np.ndarray, value, valid_idx : np.ndarray):
    idx = 0;
    min_diff = array[len(array) - 1];
    for i in range(len(array)):
        if (i % 12) not in valid_idx:
            continue
        diff = abs(value - array[i])
        if diff < min_diff:
            min_diff = diff
            idx = i
    return array[idx]
